 $('#connect').setAttribute('aria-pressed',linking);$('#map-hint').textContent=linking?(linkStart?'Select the second theme':'Select the first theme'):'Themes & connections';$('#remove-edge').disabled=!data.edges.some(e=>e.id===selected);renderKeywordPanel();
