 const needs=live.filter(c=>gaps(c).length),recent=[...live].filter(c=>!needs.slice(0,5).includes(c)).sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,4),unfiled=data.papers.filter(p=>!p.keywords.some(getKeyword));
