function editKeyword(id){const k=getKeyword(id);modal(k?'Edit theme':'Add theme',`<form><label>Theme<input name="title" required maxlength="100" value="${esc(k?.title||'')}" autofocus></label><label>Short introduction (optional)<textarea name="note" rows="2" maxlength="300" placeholder="What this theme means in your thesis. Shown when you hover over it on the map.">${esc(k?.note||'')}</textarea></label>${colourPicker(k)}${actions()}</form>`,f=>{const title=f.get('title').trim();if(!title)throw Error('Enter a theme.');const note=(f.get('note')||'').trim();if(k){k.title=title;k.note=note;k.color=Number(f.get('color'));}else{const n=data.keywords.length;const fresh={id:uid(),title,note,color:Number(f.get('color')),x:40+n%3*290+(n%2)*30,y:40+Math.floor(n/3)*120+(n%3)*26};data.keywords.push(fresh);selected=fresh.id;}save();closeModal();render();});}
function assignPapers(id){modal('Literature in this theme',`<p>A paper can be linked to more than one theme.</p><form><div class="check-list">${alpha(data.papers).map(p=>`<label><input type="checkbox" name="paper" value="${esc(p.id)}" ${p.keywords.includes(id)?'checked':''}><span>${esc(p.title)}<small>${esc(p.author)}</small></span></label>`).join('')||'<p>No papers yet. Add literature first.</p>'}</div>${actions('Save links')}</form>`,f=>{const ids=f.getAll('paper');for(const p of data.papers)p.keywords=ids.includes(p.id)?[...new Set([...p.keywords,id])]:p.keywords.filter(x=>x!==id);save();closeModal();render();});}
function setupDrag(){const c=$('#canvas');let drag=null,moved=false,suppress=false;
 c.onpointerdown=e=>{const b=e.target.closest('[data-keyword]');if(!b||linking||e.button!==0)return;const k=getKeyword(b.dataset.keyword);drag={id:k.id,x:k.x,y:k.y,px:e.clientX,py:e.clientY};moved=false;};
 c.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.px,dy=e.clientY-drag.py;if(!moved&&Math.hypot(dx,dy)<5)return;c.setPointerCapture(e.pointerId);moved=true;const k=getKeyword(drag.id);k.x=Math.max(8,drag.x+dx);k.y=Math.max(8,drag.y+dy);selected=k.id;drawMap();};
 c.onpointerup=e=>{if(!drag)return;if(c.hasPointerCapture(e.pointerId))c.releasePointerCapture(e.pointerId);drag=null;if(moved){suppress=true;save();}};c.onpointercancel=()=>{drag=null;save();};
 c.onclick=e=>{if(suppress){suppress=false;return;}const b=e.target.closest('[data-keyword]'),edge=e.target.closest('[data-edge]');if(edge){selected=edge.dataset.edge;drawMap();return;}if(!b){if(!linking&&(selected||libraryKeyword!=='all'))filterByTheme(null);return;}selected=b.dataset.keyword;if(!linking){filterByTheme(selected);return;}if(linking){if(!linkStart)linkStart=selected;else if(linkStart!==selected){if(!data.edges.some(x=>(x.a===linkStart&&x.b===selected)||(x.b===linkStart&&x.a===selected)))data.edges.push({id:uid(),a:linkStart,b:selected});linking=false;linkStart=null;save();}}drawMap();};
 
 c.onkeydown=e=>{if(e.target.dataset.keyword&&e.key==='Enter'&&!linking){e.preventDefault();openKeyword(e.target.dataset.keyword);return;}if(e.target.dataset.edge&&['Enter',' '].includes(e.key)){e.preventDefault();selected=e.target.dataset.edge;drawMap();}};
}
function renderLibrary(){if(libraryKeyword!=='all'&&!getKeyword(libraryKeyword))libraryKeyword='all'; $('#main').innerHTML=`<div class="page-heading"><div>${libraryKeyword==='all'?'':`<span class="heading-swatch" style="--tag:${colors[getKeyword(libraryKeyword).color%colors.length]}"></span>`}<h1>${libraryKeyword==='all'?'Literature':esc(getKeyword(libraryKeyword).title)}</h1><p>${libraryKeyword==='all'?'Papers, reading progress, and relevance to your research.':'All literature in this theme folder.'}</p></div><div class="actions">${libraryKeyword!=='all'?`<button data-edit-theme="${esc(libraryKeyword)}">Edit theme</button>`:''}${libraryKeyword!=='all'?'<button data-clear-theme>Show all papers</button>':''}${moreMenu('<button id="fill-apa">Fill in missing APA references</button><button id="import-chat">Import a conversation</button>')}<button id="batch-add">Add several…</button><button id="add-paper" class="primary">＋ Add literature</button></div></div>${themeMapHTML()}<div class="search-row"><input id="search-papers" aria-label="Search literature" placeholder="Search title, author, or theme" value="${esc(query)}"><select id="keyword-library-filter" aria-label="Theme filter"><option value="all">All themes</option>${alpha(data.keywords).map(k=>`<option value="${esc(k.id)}" ${libraryKeyword===k.id?'selected':''}>${esc(k.title)}</option>`).join('')}</select><select id="status-filter" aria-label="Reading status filter">${['All','To read','Reading','Read'].map(s=>`<option ${s===readingStatus?'selected':''}>${s}</option>`).join('')}</select></div><div class="list" id="paper-list"></div>`;$('#keyword-library-filter').onchange=e=>filterByTheme(e.target.value==='all'?null:e.target.value);$('#import-chat').onclick=()=>importThread();bindThemeMap();$('#add-paper').onclick=()=>addPaper();$('#search-papers').oninput=e=>{query=e.target.value;paperList();};$('#status-filter').onchange=e=>{readingStatus=e.target.value;paperList();};paperList();}
// Literature is grouped by each paper's first theme, in theme-map order; the first file of a group carries its tab.
const primaryTheme=p=>p.keywords.find(id=>getKeyword(id))||null;
function sortByTheme(papers){const order=new Map(data.keywords.map((k,i)=>[k.id,i]));return [...papers].sort((a,b)=>(order.get(primaryTheme(a))??1e9)-(order.get(primaryTheme(b))??1e9));}
function themeGroups(list){let index=-1;return list.map((p,i)=>{const t=primaryTheme(p),start=i===0||primaryTheme(list[i-1])!==t;if(start)index++;return {start,index,size:list.filter(q=>primaryTheme(q)===t).length};});}
function paperList(){const list=sortByTheme(data.papers.filter(p=>(libraryKeyword==='all'||p.keywords.includes(libraryKeyword))&&(readingStatus==='All'||p.status===readingStatus)&&`${p.title} ${p.author} ${p.keywords.map(k=>getKeyword(k)?.title||'').join(' ')}`.toLowerCase().includes(query.toLowerCase())));const groups=themeGroups(list);$('#paper-list').innerHTML='<div class="filing-caption"><span>Literature index</span><span>'+plural(list.length,'record')+'</span></div><p class="drawer-hint">Hover to pull out a file · Click or tap to keep it open</p><div class="file-stack stacked-drawer">'+(list.map((p,i)=>{const ks=p.keywords.map(getKeyword).filter(Boolean),tone=ks.length?colors[ks[0].color%colors.length]||colors[0]:'#ded9c4',g=groups[i];return `<article class="file-record drawer-file${g.start?' group-start':''}" style="--file-color:${tone};--tab-shift:${g.index%3*18}px"><div class="file-sheet"><button class="file-spine" aria-expanded="false" aria-controls="file-detail-${esc(p.id)}" aria-label="Preview ${esc(p.title)}">${g.start?`<span class="spine-tab">${esc(ks[0]?.title||'No theme')}<small>${g.size}</small></span>`:''}<span class="spine-title">${esc(p.title)}</span><span class="spine-number"><span class="spine-arrow" aria-hidden="true">+</span></span></button><div class="file-reveal" id="file-detail-${esc(p.id)}"><div class="file-reveal-inner"><div class="file-tabs">${ks.length?ks.map(k=>`<button class="file-tab" data-open-keyword="${esc(k.id)}" style="--tab-color:${colors[k.color%colors.length]||colors[0]}">${esc(k.title)}</button>`).join(''):'<span class="file-tab">Unfiled</span>'}</div><div class="file-body"><span class="number">${String(i+1).padStart(2,'0')}</span><div class="file-label"><h3><button class="paper-title" data-paper="${esc(p.id)}">${esc(p.title)}</button></h3><p>${esc([p.author,p.year].filter(Boolean).join(' · ')||'Bibliographic details not entered')}</p>${typeof apaHTML==='function'&&p.apa?`<p class="apa-small">${apaHTML(p.apa)} <button class="link" data-copy-apa="${esc(p.id)}">Copy</button></p>`:''}<small>${esc(p.status)} · ${data.passages.filter(h=>h.paperId===p.id).length} saved passages</small></div><div class="file-actions"><button data-paper="${esc(p.id)}" aria-label="Open ${esc(p.title)}">Open ↗</button><button data-edit-paper="${esc(p.id)}">Edit details</button><button class="danger" data-delete-paper="${esc(p.id)}" aria-label="Delete ${esc(p.title)}">Delete</button></div></div></div></div></div></article>`;}).join('')||empty('No matching literature',data.papers.length?'Try another search or filter.':'Add a paper or import bibliography records to begin.'))+'</div><div class="drawer-front"><span>Theesees</span><small>Literature · Theme colours match your map</small></div>';setupFileDrawer();}
function setupFileDrawer(){
 for(const record of $$('.drawer-file')){
  const button=record.querySelector('.file-spine');let hovering=false;
  const update=()=>{const open=hovering||record.classList.contains('is-pinned')||record.contains(document.activeElement);record.classList.toggle('is-pulled',open);button.setAttribute('aria-expanded',String(open));};
  record.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){hovering=true;update();}});
  record.addEventListener('pointerleave',()=>{hovering=false;update();});
  record.addEventListener('focusin',update);
  record.addEventListener('focusout',()=>setTimeout(update,0));
  button.onclick=()=>{const pinned=record.classList.toggle('is-pinned');if(!pinned){hovering=false;button.blur();}update();};
  record.addEventListener('keydown',e=>{if(e.key==='Escape'){record.classList.remove('is-pinned');hovering=false;button.focus();record.classList.remove('is-pulled');button.setAttribute('aria-expanded','false');e.preventDefault();}});
 }
}
function keywordChecks(ids=[]){return `<div class="check-list">${alpha(data.keywords).map(k=>`<label><input type="checkbox" name="keyword" value="${esc(k.id)}" ${ids.includes(k.id)?'checked':''}><span>${esc(k.title)}</span></label>`).join('')||'<p class="help">No themes yet. You can add them on the map later.</p>'}</div>`;}
function addPaper(){modal('Add literature',`<form><label>Title<input name="title" required maxlength="500"></label><div class="two-col"><label>Author(s)<input name="author"></label><label>Year<input name="year" maxlength="20"></label></div><label>Source text / excerpt (optional)<textarea name="text" placeholder="Paste the original text you want to read and highlight."></textarea></label><label>PDF (optional)<input type="file" name="pdf" accept="application/pdf"></label><p class="help">PDFs are stored in this browser. Text selection is available in pasted text, not inside the PDF preview.</p><label>Themes</label>${keywordChecks(libraryKeyword!=='all'&&page==='library'?[libraryKeyword]:[])}${actions('Add paper')}</form>`,async(f,form)=>{const title=f.get('title').trim();if(!title)throw Error('Enter a title.');const p={id:uid(),title,author:f.get('author').trim(),year:f.get('year').trim(),text:f.get('text'),status:'To read',relevance:'',keywords:f.getAll('keyword'),pdfName:''};const file=form.elements.pdf.files[0];if(file){await putPDF(p.id,file);p.pdfName=file.name;}data.papers.push(p);save();closeModal();openPaper(p.id);});}
// PDFs use IndexedDB rather than localStorage; no files leave this browser.
let dbPromise;
function pdfDB(){return dbPromise||=(new Promise((resolve,reject)=>{const req=indexedDB.open('theesees-files',2);req.onupgradeneeded=()=>{const db=req.result;for(const s of ['pdfs','images'])if(!db.objectStoreNames.contains(s))db.createObjectStore(s);};req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result);};req.onerror=()=>reject(Error('PDF storage is unavailable. Add the paper without a PDF.'));req.onblocked=()=>{storageBlocked=true;toast('Theesees is open in another tab with an older version. Close your other Theesees tabs and this will continue.',20000);};}));}
let storageBlocked=false;
async function putPDF(id,file){if(file.size>30*1024*1024)throw Error('Please use a PDF smaller than 30 MB.');if(file.type&&file.type!=='application/pdf')throw Error('Choose a PDF file.');const db=await pdfDB();return new Promise((res,rej)=>{const t=db.transaction('pdfs','readwrite');t.objectStore('pdfs').put(file,id);t.oncomplete=res;t.onerror=t.onabort=()=>rej(Error('Could not store the PDF. Browser storage may be full.'));});}
async function deletePDF(id){const db=await pdfDB();return new Promise((res,rej)=>{const t=db.transaction('pdfs','readwrite');t.objectStore('pdfs').delete(id);t.oncomplete=res;t.onerror=t.onabort=()=>rej(Error('Could not remove the PDF from browser storage.'));});}
function removePDF(p){
 modal('Remove PDF?',`<p>Remove “${esc(p.pdfName)}” from this paper? The file is deleted from this browser’s storage and does not go to Trash, so keep your own copy. Passages, quotes and discussions stay; attach the PDF again and its passages are found again.</p><form>${actions('Remove PDF')}</form>`,async()=>{
  await deletePDF(p.id);
  if(typeof pdfState!=='undefined'&&pdfState?.paperId===p.id){pdfState.doc?.destroy();pdfState=null;}
  p.pdfName='';p.readingMode='text';for(const h of data.passages.filter(h=>h.paperId===p.id))for(const k of ['pdfPage','pdfMatch','pdfQuote','pdfFile'])delete h[k];
  save();closeModal();renderReader();toast('PDF removed from this paper.');
 });
}
async function getPDF(id){const db=await pdfDB();return new Promise((res,rej)=>{const r=db.transaction('pdfs').objectStore('pdfs').get(id);r.onsuccess=()=>res(r.result);r.onerror=rej;});}
const passageDrafts={};
const usingPDF=p=>!!p.pdfName&&p.readingMode!=='text';
function setPDFView(expand){
 const viewer=$('#pdf-preview');if(!viewer)return;
 viewer.classList.toggle('pdf-focused',expand);document.body.classList.toggle('pdf-focused-body',expand);
 const button=$('#pdf-fullscreen');if(button){button.textContent=expand?'Exit full-screen PDF':'Full-screen PDF';button.setAttribute('aria-pressed',expand);}
 if(expand&&viewer.requestFullscreen){viewer.requestFullscreen().catch(()=>toast('Full-screen is unavailable here; the PDF now fills this window.'));}
 else if(!expand&&document.fullscreenElement)document.exitFullscreen().catch(()=>{});
}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){$('#pdf-preview')?.classList.remove('pdf-focused');document.body.classList.remove('pdf-focused-body');const b=$('#pdf-fullscreen');if(b){b.textContent='Full-screen PDF';b.setAttribute('aria-pressed','false');}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#pdf-preview')?.classList.contains('pdf-focused'))setPDFView(false);});
function updateOriginalText(p,text){
 const before=structuredClone(data);
 p.textHistory=[...(p.textHistory||[]),{text:p.text,at:new Date().toISOString()}];p.text=text;
 for(const h of data.passages.filter(h=>h.paperId===p.id)){
  if(!Number.isInteger(h.start)&&!h.sourceDetached)continue;
  const anchor=passageAnchor(p,{start:null},h.quote);
  Object.assign(h,anchor,{sourceDetached:anchor.start===null});
 }
 if(!save()){data=before;return false;}selection=null;return true;
}
function editOriginalText(){
 const p=getPaper(currentPaper);
 modal(p.text?'Edit original text':'Add original text',`<p>Saved quotations and discussions are kept. Highlights are re-linked only when their quote has one exact match in the new text.</p><form><label>Original text<textarea name="text" rows="12" required>${esc(p.text)}</textarea></label>${actions('Save original text')}</form>`,f=>{if(!f.get('text').trim())throw Error('Enter text, or use Clear text instead.');if(updateOriginalText(p,f.get('text'))){closeModal();renderReader();}});
}
function clearOriginalText(){
 const p=getPaper(currentPaper);
 modal('Clear original text?',`<p>Remove the pasted text from this paper? Saved quotations and discussions will stay. You can restore the previous text afterward.</p><form>${actions('Clear text')}</form>`,()=>{if(updateOriginalText(p,'')){closeModal();renderReader();toast('Original text cleared. Saved passages kept; previous text can be restored.');}});
}
function passageComposer(p){
 const draft=passageDrafts[p.id]||{};
 return `<form class="passage-composer" id="passage-composer"><label for="quick-quote">Paste a passage</label><textarea id="quick-quote" name="quote" rows="3" required placeholder="Click here and paste text copied from your PDF or another source.">${esc(draft.quote||'')}</textarea><div class="composer-bottom"><input name="location" aria-label="Passage page or location" required placeholder="Page / location, e.g. p. 12" value="${esc(draft.location||'')}"><button class="warm" type="submit">Save passage</button></div><small id="quick-passage-status" role="status">Your quotation and page reference will be saved together.</small></form>`;
}
function bindPassageComposer(){
 const f=$('#passage-composer'),pid=currentPaper;if(!f)return;
 f.oninput=()=>{passageDrafts[pid]={quote:f.elements.quote.value,location:f.elements.location.value};};
 f.onsubmit=e=>{e.preventDefault();const quote=f.elements.quote.value.trim(),location=f.elements.location.value.trim();if(!quote||!location){$('#quick-passage-status').textContent='Enter a quotation and page or location.';return;}
 const h={id:uid(),paperId:pid,quote,location,start:null,end:null};data.passages.push(h);if(!save()){data.passages.pop();return;}
 delete passageDrafts[pid];activePassage=h.id;refreshReaderPassages();$('#quick-passage-status').textContent='Passage saved below. You can edit, delete, or add a discussion.';};
}
function showReaderSource(id){
 const h=data.passages.find(h=>h.id===id),p=getPaper(currentPaper);if(!h||!p)return;
 if(usingPDF(p)){$('#pdf-preview')?.scrollIntoView({block:'start',behavior:'smooth'});pdfLocate(id);return;}
 const mark=$('#source-text mark').find(m=>m.dataset.highlight===id);
 if(mark)mark.scrollIntoView({block:'center',behavior:'smooth'});else toast('No exact highlight available. The saved quotation and location are still kept.');
}
let pdfURL=null,readingExpanded=false,readingNotesHidden=false;
function syncReadingView(){
 const active=page==='reader'&&readingExpanded;
 $('#main').classList.toggle('reading-expanded',active);document.body.classList.toggle('reading-expanded-body',active);
 $('#main').classList.toggle('reading-hide-notes',page==='reader'&&readingNotesHidden);
 const expand=$('#expand-reading');if(expand){expand.textContent=active?'↙ Exit expanded view':'⛶ Expand reading';expand.setAttribute('aria-pressed',active);}
 const notes=$('#toggle-reading-notes');if(notes){notes.setAttribute('aria-pressed',!readingNotesHidden);notes.textContent=readingNotesHidden?'Show passages':'Hide passages';}
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').open&&readingExpanded){readingExpanded=false;syncReadingView();$('#expand-reading')?.focus();}});
function refreshReaderPassages(){
 if($('#source-text'))$('#source-text').innerHTML=sourceHTML(getPaper(currentPaper));selection=null;if($('#save-selection'))$('#save-selection').hidden=true;renderPassages();
}
function openPaper(id,passage=null){readingExpanded=false;readingNotesHidden=false;currentPaper=id;activePassage=passage;selection=null;page='reader';render();}
function sourceHTML(p){const hs=data.passages.filter(h=>h.paperId===p.id&&Number.isInteger(h.start)).sort((a,b)=>a.start-b.start);let out='',pos=0;for(const h of hs){if(h.start<pos||p.text.slice(h.start,h.end)!==h.quote)continue;out+=esc(p.text.slice(pos,h.start))+`<mark data-highlight="${esc(h.id)}" class="${h.id===activePassage?'active':''}">${esc(h.quote)}</mark>`;pos=h.end;}return out+esc(p.text.slice(pos));}
function renderReader(){const p=getPaper(currentPaper);if(!p){navigate('library');return;}$('#main').style?.setProperty?.('--theme',themeColor(p.keywords));if(pdfURL){URL.revokeObjectURL(pdfURL);pdfURL=null;}
 $('#main').innerHTML=`<div class="reader-heading"><button class="link back" id="back-library">← Literature</button><h1>${esc(p.title)}</h1><p>${esc([p.author,p.year].filter(Boolean).join(' · '))}</p>${typeof apaHTML==='function'&&p.apa?`<p class="apa-line"><span>${apaHTML(p.apa)}</span><button data-copy-apa="${esc(p.id)}">Copy APA</button></p>`:''}</div><div class="reader-meta"><label>Progress<select id="paper-status">${['To read','Reading','Read'].map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="relevance">Relevance<input id="relevance" value="${esc(p.relevance)}" placeholder="How this paper relates to your research"></label><button id="paper-keywords">Themes (${p.keywords.length})</button><button data-discussions-paper="${esc(p.id)}">Discussions</button>${moreMenu(`<button data-edit-paper="${esc(p.id)}">Edit details</button><button class="danger" data-delete-paper="${esc(p.id)}">Delete paper</button>`)}</div>${relatedLiterature(p)}<div class="reading-layout pdf-first"><section class="source-pane"><div class="reading-toolbar"><h2>${usingPDF(p)?'Read PDF':'Read text'}</h2><div class="actions"><button id="expand-reading" aria-pressed="${readingExpanded}">${readingExpanded?'↙ Exit expanded view':'⛶ Expand reading'}</button><button id="toggle-reading-notes" aria-pressed="${!readingNotesHidden}">Passages</button><button id="capture" class="primary">＋ Add passage</button>${moreMenu(`${p.pdfName?`<button id="reading-mode">${usingPDF(p)?'Read pasted text instead':'Read attached PDF'}</button>`:''}<button id="attach-pdf">${p.pdfName?'Replace PDF':'Attach PDF'}</button>${p.pdfName?'<button id="remove-pdf" class="danger">Remove PDF</button>':''}`)}</div></div>${usingPDF(p)?'<div id="pdf-preview"><p class="help">Loading PDF…</p></div>':`<section id="excerpt-panel" class="original-text-panel"><div class="section-top"><h2>Original text</h2><div class="actions"><button id="edit-original">${p.text?'Edit text':'Add text'}</button>${p.text?'<button id="clear-original" class="danger">Clear text</button>':''}${p.textHistory?.length?'<button id="restore-original">Restore previous text</button>':''}</div></div><p class="help">Select a quotation, then click “Save selected text”. You can edit or clear this original text at any time.</p><button id="save-selection" class="warm" hidden>Save selected text</button><article class="source-text" id="source-text">${p.text?sourceHTML(p):'Add or paste the text you want to read.'}</article></section>`}</section><section class="record-pane" id="record-pane"></section></div>`;
 $('#back-library').onclick=()=>navigate('library');$('#paper-status').onchange=e=>{p.status=e.target.value;save();};$('#relevance').oninput=e=>{p.relevance=e.target.value;save();};$('#paper-keywords').onclick=()=>modal('Paper themes',`<form>${keywordChecks(p.keywords)}${actions()}</form>`,f=>{p.keywords=f.getAll('keyword');save();closeModal();renderReader();});
 if($('#edit-original'))$('#edit-original').onclick=editOriginalText;
 if($('#clear-original'))$('#clear-original').onclick=clearOriginalText;
 if($('#restore-original'))$('#restore-original').onclick=()=>{const previous=p.textHistory.at(-1).text;if(updateOriginalText(p,previous)){renderReader();toast('Previous text restored.');}};
 if($('#remove-pdf'))$('#remove-pdf').onclick=()=>removePDF(p);
 if($('#reading-mode'))$('#reading-mode').onclick=()=>{p.readingMode=usingPDF(p)?'text':'pdf';save();renderReader();};
 $('#attach-pdf').onclick=()=>modal('Attach PDF','<p>The PDF stays in this browser. It is not sent to an AI service.</p><form><label>PDF<input type="file" name="pdf" accept="application/pdf" required></label>'+actions()+'</form>',async(f,form)=>{const file=form.elements.pdf.files[0];await putPDF(p.id,file);if(pdfState?.paperId===p.id){pdfState.doc?.destroy();pdfState=null;}p.pdfName=file.name;p.readingMode='pdf';save();closeModal();renderReader();});
 if($('#source-text'))$('#source-text').onmouseup=()=>{const s=window.getSelection(),el=$('#source-text');if(!s||s.isCollapsed||!el.contains(s.anchorNode)||!el.contains(s.focusNode)){selection=null;$('#save-selection').hidden=true;return;}const r=s.getRangeAt(0),pre=r.cloneRange();pre.selectNodeContents(el);pre.setEnd(r.startContainer,r.startOffset);selection={start:pre.toString().length,end:pre.toString().length+r.toString().length,quote:r.toString()};$('#save-selection').hidden=false;};
 $('#capture').onclick=()=>{readingNotesHidden=false;syncReadingView();$('#quick-quote').focus();$('#passage-composer').scrollIntoView({block:'center',behavior:'smooth'});};
 if($('#save-selection'))$('#save-selection').onclick=()=>savePassage();
 $('#expand-reading').onclick=()=>{readingExpanded=!readingExpanded;syncReadingView();};
 $('#toggle-reading-notes').onclick=()=>{readingNotesHidden=!readingNotesHidden;syncReadingView();};
 syncReadingView();renderPassages();
 if(usingPDF(p))getPDF(p.id).then(file=>{if(page!=='reader'||currentPaper!==p.id||!usingPDF(p))return;if(file){pdfURL=URL.createObjectURL(file);mountPDFReader(file,p,pdfURL);}else $('#pdf-preview').textContent='PDF file is missing from this browser. Please attach it again.';}).catch(()=>toast('Could not load the saved PDF.'));

}
function savePassage(){const p=getPaper(currentPaper),sel=selection&&p.text.slice(selection.start,selection.end)===selection.quote?selection:null;modal('Save source passage',`<p>${sel?'The selected text will stay linked to its exact position in this source.':'Copy text from the PDF, paste it below, and enter the page number. The PDF selection cannot be captured automatically.'}</p><form><label>Quoted passage<textarea name="quote" required >${esc(sel?.quote||'')}</textarea></label><label>Page / section / location<input name="location" required placeholder="e.g. p. 12, paragraph 2"></label>${actions('Save passage')}</form>`,f=>{const quote=f.get('quote').trim();if(!quote)throw Error('Enter a passage.');const h={id:uid(),paperId:p.id,quote,location:f.get('location').trim(),...(sel?passageAnchor(p,sel,quote):{start:null,end:null})};data.passages.push(h);activePassage=h.id;selection=null;save();closeModal();refreshReaderPassages();});}
function passageAnchor(p,h,quote){
 if(Number.isInteger(h.start)&&p.text.slice(h.start,h.start+quote.length)===quote)return {start:h.start,end:h.start+quote.length};
 const first=p.text.indexOf(quote);
 return first>=0&&p.text.indexOf(quote,first+1)===-1?{start:first,end:first+quote.length}:{start:null,end:null};
}
function editPassage(id){
 const h=data.passages.find(x=>x.id===id),p=h&&getPaper(h.paperId);if(!p)return;
 modal('Edit passage',`<p>Edit the quotation or its location. The literature’s original text is never changed; linked discussions stay attached.</p><form><label>Quoted passage<textarea name="quote" required rows="6">${esc(h.quote)}</textarea></label><label>Page / section / location<input name="location" required value="${esc(h.location)}"></label><p class="help" id="passage-edit-status" role="status"></p>${actions('Save changes')}</form>`,f=>{
  const quote=f.get('quote'),location=f.get('location').trim();if(!quote.trim()||!location)throw Error('Enter a quotation and location.');
  const before=structuredClone(h),anchor=passageAnchor(p,h,quote);
  h.history=[...(h.history||[]),{quote:h.quote,location:h.location,start:h.start,end:h.end,at:new Date().toISOString()}];
  Object.assign(h,{quote,location,...anchor,sourceDetached:false});if(!save()){Object.keys(h).forEach(k=>delete h[k]);Object.assign(h,before);return;}
  activePassage=id;selection=null;closeModal();refreshReaderPassages();toast(anchor.start===null?'Passage updated as a manually supplied quote.':'Passage updated and linked to source text.');
 });
 const input=$('#modal-body textarea[name="quote"]');
 const update=()=>{$('#passage-edit-status').textContent=passageAnchor(p,h,input.value).start===null?'This text has no unique match in the saved source. It will be marked as manually supplied, without a source highlight.':'This quotation matches the saved source. Its highlight will be updated.';};
 input.oninput=update;update();
}
function deletePassage(id){
 const h=data.passages.find(x=>x.id===id);if(!h)return;
 modal('Delete passage?',`<blockquote>${esc(h.quote)}</blockquote><p>This passage and its highlight will move to Trash. Linked discussions will be kept under this literature; only their link to this passage is removed.</p><form>${actions('Move to Trash')}</form>`,()=>{
  const before=structuredClone(data),threads=data.threads.filter(t=>t.passageIds.includes(id));
  data.trash.push({id:uid(),type:'passage',item:structuredClone(h),threadIds:threads.map(t=>t.id),at:new Date().toISOString()});
  for(const t of threads){t.paperIds=[...new Set([...(t.paperIds||[]),h.paperId])];t.passageIds=t.passageIds.filter(x=>x!==id);}
  data.passages=data.passages.filter(x=>x.id!==id);
  if(!save()){data=before;return;}if(activePassage===id)activePassage=null;selection=null;closeModal();refreshReaderPassages();toast('Passage moved to Trash. Discussions kept.');
 });
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-edit-passage],[data-delete-passage]');if(!b)return;if(b.dataset.editPassage)editPassage(b.dataset.editPassage);else deletePassage(b.dataset.deletePassage);});
function renderPassages(){const hs=data.passages.filter(h=>h.paperId===currentPaper);$('#record-pane').innerHTML=`${passageComposer(getPaper(currentPaper))}<div class="section-top"><h2>Passages & discussions</h2><span class="badge">${plural(hs.length,'passage')}</span></div>${hs.map(h=>{const threads=data.threads.filter(t=>t.passageIds.includes(h.id));return `<article class="passage ${h.id===activePassage?'active':''}" id="passage-${esc(h.id)}"><small>${esc(h.location)} · ${usingPDF(getPaper(h.paperId))&&typeof pdfPassageLabel==='function'?pdfPassageLabel(h):h.sourceDetached?'Saved quote · original text changed':h.start===null?'Manually supplied quote':'Linked to source text'}</small><blockquote>${esc(h.quote)}</blockquote><div class="actions"><button data-jump="${esc(h.id)}">Show source</button><button data-start-discussion="${esc(h.id)}">＋ Discussion</button>${moreMenu(`<button data-edit-passage="${esc(h.id)}">Edit passage</button><button data-import-for="${esc(h.id)}">Import a conversation</button><button data-attach-thread="${esc(h.id)}">Link an existing discussion</button><button class="danger" data-delete-passage="${esc(h.id)}">Delete passage</button>`)}</div>${typeof passageClaimsHTML==='function'?passageClaimsHTML(h):''}${threads.map(t=>`<div class="discussion-card"><span class="badge">${esc(t.status)}</span><h3>${esc(t.title)}</h3><p>${esc(t.transcript.slice(0,160))}${t.transcript.length>160?'…':''}</p><button data-thread="${esc(t.id)}">View discussion ↗</button></div>`).join('')||'<p class="help">No discussions linked to this passage.</p>'}</article>`;}).join('')||empty('No saved passages','Select a sentence in the source text, or save a quotation from your PDF with its page number.')}`;bindPassageComposer();if(typeof pdfSyncMatches==='function'&&usingPDF(getPaper(currentPaper)))pdfSyncMatches();}

function discussionView(t){
 const raw=t.transcript.trim();let link=null;
 if(/^https?:\/\/\S+$/i.test(raw)){try{link=new URL(raw).href;}catch{}}
 if(link)return `<div class="conversation-link"><h3>Conversation link only</h3><p>The conversation text has not been imported. Paste the actual messages using “Edit discussion” to read them here.</p><a href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open shared conversation ↗</a></div>`;
 const turns=conversationTurns(raw);
 return `<div class="conversation-controls"><span>${turns.length} ${turns.some(t=>t.speaker!=='Unlabelled text')?'message sections':'text sections'}</span><button data-turns-open="true">Expand all</button><button data-turns-open="false">Collapse all</button><label><input type="checkbox" id="readable-chat" checked> Join wrapped lines</label></div>${turns.every(t=>t.speaker==='Unlabelled text')?'<p class="help">No speaker labels detected. Edit the discussion and add “User:” / “Assistant:” on separate lines to separate turns. Speakers are never guessed.</p>':''}<div class="conversation-turns">${turns.map((m,i)=>`<details class="conversation-turn" ${m.body.length<1200?'open':''}><summary><span>${esc(m.speaker)}</span><small>${i+1}</small><p>${esc(m.body.replace(/\s+/g,' ').slice(0,130))}${m.body.length>130?'…':''}</p></summary><div class="message-body" data-message-index="${i}">${esc(cleanPDFBreaks(m.body))}</div></details>`).join('')}</div><details class="raw-conversation"><summary>Original imported text (unchanged)</summary><pre>${esc(t.transcript)}</pre></details>`;
}
function editDiscussion(id){
 const t=data.threads.find(t=>t.id===id);if(!t)return;
 modal('Edit discussion',`<p>Use speaker labels such as User: and Assistant: to separate messages. A share URL alone does not import its conversation.</p><form><label>Discussion title<input name="title" required value="${esc(t.title)}"></label><div class="two-col"><label>Status<select name="status">${['Open','Revised','Resolved'].map(s=>`<option ${s===(t.status||'Open')?'selected':''}>${s}</option>`).join('')}</select></label><label>Platform<select name="platform">${[...new Set([t.platform||'Other','ChatGPT','Claude','Personal notes / AI conversations','Other'])].map(s=>`<option ${s===t.platform?'selected':''}>${esc(s)}</option>`).join('')}</select></label></div><label>Conversation text<textarea name="transcript" rows="12">${esc(t.transcript)}</textarea></label>${actions('Save discussion')}</form>`,f=>{
  const title=f.get('title').trim(),transcript=f.get('transcript').trim();if(!title)throw Error('Enter a title.');
  const before=structuredClone(t);t.revisions=[...(t.revisions||[]),{title:t.title,transcript:t.transcript,at:new Date().toISOString()}];Object.assign(t,{title,transcript,status:f.get('status'),platform:f.get('platform')});
  if(!save()){Object.assign(t,before);return;}closeModal();renderThread();
 });
}
function deleteDiscussion(id){
 const t=data.threads.find(t=>t.id===id);if(!t)return;
 modal('Delete discussion?',`<p>Move “${esc(t.title)}” to Trash? Papers and passages stay unchanged. You can restore this conversation and its links later.</p><form>${actions('Move to Trash')}</form>`,()=>{
  const before=structuredClone(data);data.trash.push({id:uid(),type:'thread',item:structuredClone(t),at:new Date().toISOString()});data.threads=data.threads.filter(t=>t.id!==id);
  if(!save()){data=before;return;}closeModal();navigate('archive');toast('Discussion moved to Trash. You can restore it there.');
 });
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-delete-thread],[data-edit-thread],[data-turns-open]');if(!b)return;
 if(b.dataset.deleteThread)deleteDiscussion(b.dataset.deleteThread);
 else if(b.dataset.editThread)editDiscussion(b.dataset.editThread);
 else $('.conversation-turn').forEach(d=>d.open=b.dataset.turnsOpen==='true');
});

function importThread(passageId=null){modal('Import discussion',`<p>Add your own title. The original conversation is kept as supplied; no AI summary or source match is inferred.</p><form><label>Discussion title<input name="title" required maxlength="250"></label><label>Platform<select name="platform"><option>ChatGPT</option><option>Claude</option><option>Other</option></select></label><label>Conversation file (optional)<input type="file" id="chat-file" accept=".txt,.md,.json,text/plain,application/json"></label><label>Original conversation<textarea name="transcript" id="chat-text" required rows="8" placeholder="Paste messages with labels such as User: and Assistant: on separate lines. A share link alone does not import messages."></textarea></label><p class="help">TXT and Markdown are kept as text. JSON is retained as raw JSON; vendor-specific chat exports are not reconstructed.</p><label>Literature (optional)<select name="paper"><option value="">Choose later</option>${alpha(data.papers).map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')}</select></label><p class="help">${passageId?'This discussion will be linked to the selected passage.':'No source attached yet. You can link passages after importing.'}</p>${actions('Import discussion')}</form>`,f=>{const title=f.get('title').trim(),transcript=f.get('transcript').trim();if(!title||!transcript)throw Error('Enter a title and conversation.');const t={id:uid(),title,platform:f.get('platform'),transcript,paperIds:f.get('paper')?[f.get('paper')]:[],question:'',understanding:'',changed:'',unresolved:'',status:'Open',passageIds:passageId?[passageId]:[],history:[],created:new Date().toISOString()};data.threads.push(t);save();closeModal();openThread(t.id);});$('#chat-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){toast('Use a conversation file smaller than 2 MB.');return;}try{$('#chat-text').value=await f.text();}catch{toast('Could not read this file. Paste the conversation instead.');}};}

function threadPassages(t){return t.passageIds.map(id=>data.passages.find(h=>h.id===id)).filter(h=>h&&getPaper(h.paperId));}
function threadPapers(t){return [...new Set([...(t.paperIds||[]),...threadPassages(t).map(h=>h.paperId)])].map(getPaper).filter(Boolean);}
function keywordTags(p){return p.keywords.map(getKeyword).filter(Boolean).map(k=>`<button class="keyword-tag" style="--tag:${colors[k.color%colors.length]||colors[0]}" data-filter-keyword="${esc(k.id)}">${esc(k.title)}</button>`).join('');}
function discussionMatches(t){const papers=threadPapers(t);return `${t.title} ${t.transcript} ${(t.blocks||[]).filter(b=>!b.deleted).map(b=>b.text).join(' ')}`.toLowerCase().includes(discussionQuery.toLowerCase())&&(archiveFilter==='All'||(archiveFilter==='Unlinked'?!threadPassages(t).length:t.status===archiveFilter))&&((discussionPaper==='all'&&discussionKeyword==='all')||papers.some(p=>(discussionPaper==='all'||p.id===discussionPaper)&&(discussionKeyword==='all'||p.keywords.includes(discussionKeyword))));}
function renderArchive(){
 if(discussionPaper!=='all'&&!getPaper(discussionPaper))discussionPaper='all';
 if(discussionKeyword!=='all'&&!getKeyword(discussionKeyword))discussionKeyword='all';
 $('#main').innerHTML=`<div class="page-heading"><div><h1>Discussions</h1><p>Browse conversations by literature and theme.</p></div><div class="actions">${moreMenu(`<button id="import-thread">Import a conversation</button>`)}<button data-start-discussion="" class="primary">＋ New discussion</button></div></div><div class="discussion-filters"><label>Search<input id="search-threads" placeholder="Title or conversation" value="${esc(discussionQuery)}"></label><label>Literature<select id="discussion-paper"><option value="all">All literature</option>${alpha(data.papers).map(p=>`<option value="${esc(p.id)}" ${discussionPaper===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><label>Theme<select id="discussion-keyword"><option value="all">All themes</option>${alpha(data.keywords).map(k=>`<option value="${esc(k.id)}" ${discussionKeyword===k.id?'selected':''}>${esc(k.title)}</option>`).join('')}</select></label><label>Source / status<select id="thread-filter">${['All','Unlinked','Open','Revised','Resolved'].map(x=>`<option ${x===archiveFilter?'selected':''}>${x}</option>`).join('')}</select></label><button id="clear-discussion-filters">Clear filters</button></div><div class="archive-count" id="archive-count" role="status"></div><div id="thread-list" class="list"></div>`;
 $('#import-thread').onclick=()=>importThread();$('#search-threads').oninput=e=>{discussionQuery=e.target.value;threadList();};$('#thread-filter').onchange=e=>{archiveFilter=e.target.value;threadList();};$('#discussion-paper').onchange=e=>{discussionPaper=e.target.value;threadList();};$('#discussion-keyword').onchange=e=>{discussionKeyword=e.target.value;threadList();};$('#clear-discussion-filters').onclick=()=>{discussionPaper=discussionKeyword='all';archiveFilter='All';discussionQuery='';renderArchive();};threadList();
}
function threadList(){const ts=data.threads.filter(discussionMatches);$('#archive-count').textContent=ts.length+' of '+plural(data.threads.length,'discussion');$('#thread-list').innerHTML=ts.map(t=>{const papers=threadPapers(t),hs=threadPassages(t);return `<article class="archive-entry"><div class="archive-entry-head"><div><span class="badge">${esc(t.platform)}</span><span class="badge">${esc(t.status||'Open')}</span><span class="badge ${!hs.length?'unlinked':''}">${hs.length?plural(hs.length,'source passage'):'No passage linked'}</span><h2><button data-thread="${esc(t.id)}" class="discussion-title-link">${esc(t.title)}</button></h2></div><div class="actions"><button data-thread="${esc(t.id)}">Open ↗</button>${moreMenu(`<button class="danger" data-delete-thread="${esc(t.id)}">Delete discussion</button>`)}</div></div><p class="help">${plural((t.blocks||[]).filter(b=>!b.deleted).length,'comment')} · ${plural((t.blocks||[]).filter(b=>b.key&&!b.deleted).length,'key thought')}</p><div class="discussion-provenance">${papers.map(p=>`<div class="paper-provenance"><button class="link" data-paper="${esc(p.id)}">${esc(p.title)}</button><div class="tag-row">${keywordTags(p)||'<small>No theme assigned</small>'}</div></div>`).join('')||'<small>No literature assigned. Open the discussion to link a paper or passage.</small>'}</div>${hs.length?`<div class="quote-preview" style="--theme:${themeColor(getPaper(hs[0].paperId)?.keywords)}"><small>${esc(getPaper(hs[0].paperId).title)} · ${esc(hs[0].location)}</small><blockquote>${esc(hs[0].quote)}</blockquote>${hs.length>1?`<small>+ ${hs.length-1} more linked passages</small>`:''}</div>`:''}</article>`;}).join('')||empty('No matching discussions','Choose another paper or theme, clear the filters, or import a conversation.');}
function openThread(id){currentThread=id;threadSource=null;page='thread';render();}
function renderThread(){const t=data.threads.find(t=>t.id===currentThread);if(!t){navigate('archive');return;}const papers=threadPapers(t),hs=threadPassages(t);if(!hs.some(h=>h.id===threadSource))threadSource=hs[0]?.id||null;$('#main').style?.setProperty?.('--theme',themeColor(papers[0]?.keywords));
 $('#main').innerHTML=`<div class="reader-heading"><button class="link back" id="back-archive">← Discussions</button><h1>${esc(t.title)}</h1><div class="actions"><button data-edit-thread="${esc(t.id)}">Edit discussion</button>${moreMenu(`<button class="danger" data-delete-thread="${esc(t.id)}">Delete discussion</button>`)}</div><p>${esc(t.platform)} · ${esc(t.status||'Open')} · Original conversation preserved</p><div class="discussion-provenance">${papers.map(p=>`<div class="paper-provenance"><button class="link" data-paper="${esc(p.id)}">${esc(p.title)}</button><div class="tag-row">${keywordTags(p)}</div></div>`).join('')||'<small>No literature assigned yet.</small>'}</div></div><div class="source-chat-layout"><section class="discussion-source"><div class="section-top"><h2>Source text</h2><button id="link-sources">Link literature / passages</button></div>${hs.length?`<label>Linked passage<select id="thread-source-choice">${hs.map(h=>`<option value="${esc(h.id)}" ${h.id===threadSource?'selected':''}>${esc(getPaper(h.paperId).title)} — ${esc(h.location)}</option>`).join('')}</select></label><div id="thread-source-content"></div>`:papers.length?`<p class="help">Literature assigned, but no passage linked yet. Use “Link literature / passages” to choose a saved passage.</p>${papers.map(p=>`<h3>${esc(p.title)}</h3><div class="thread-source-paper">${p.text?esc(p.text):'No source text available. Open this paper to read its PDF or add an excerpt.'}</div><button data-paper="${esc(p.id)}">Open paper ↗</button>`).join('')}`:empty('No linked source','Attach literature or a saved passage to see it beside the conversation.')}</section><section class="discussion-conversation"><div class="section-top"><h2>Conversation</h2><small>As imported · ${esc(t.platform)}</small></div>${threadedDiscussionView(t)}<details class="free-note"><summary>My note (optional)</summary><textarea id="free-note" aria-label="My note" placeholder="Write anything you want to keep…">${esc(t.note||'')}</textarea><small id="note-save-state">Saved automatically on this browser</small></details>${legacyNotes(t)}</section></div>`;
 if($('#readable-chat'))$('#readable-chat').onchange=e=>{const turns=conversationTurns(t.transcript);$('[data-message-index]').forEach(el=>{const raw=turns[Number(el.dataset.messageIndex)].body;el.textContent=e.target.checked?cleanPDFBreaks(raw):raw;});};
 $('#back-archive').onclick=()=>navigate('archive');$('#link-sources').onclick=()=>linkSources(t);$('#free-note').oninput=e=>{t.note=e.target.value;if(save())$('#note-save-state').textContent='Saved on this browser';};
 if(hs.length){$('#thread-source-choice').onchange=e=>{threadSource=e.target.value;renderThreadSource();};renderThreadSource();}
}
function legacyNotes(t){const fields=['question','understanding','changed','unresolved'];const labels={question:'Question',understanding:'Understanding',changed:'Changes',unresolved:'Unresolved'};const has=fields.some(k=>t[k])||(t.history||[]).length;if(!has)return '';return `<details class="legacy-notes"><summary>Previously saved notes</summary>${fields.filter(k=>t[k]).map(k=>`<p><small>${labels[k]}</small><br>${esc(t[k])}</p>`).join('')}${(t.history||[]).slice().reverse().map(h=>`<div class="discussion-card"><small>${esc(new Date(h.at).toLocaleString())}</small>${fields.filter(k=>h[k]).map(k=>`<p><strong>${labels[k]}</strong><br>${esc(h[k])}</p>`).join('')}</div>`).join('')}</details>`;}
function renderThreadSource(){const h=data.passages.find(x=>x.id===threadSource),p=h&&getPaper(h.paperId);if(!p)return;const exact=Number.isInteger(h.start)&&p.text.slice(h.start,h.end)===h.quote;const html=exact?esc(cleanPDFBreaks(p.text.slice(0,h.start)))+'<mark id="discussion-quote">'+esc(cleanPDFBreaks(h.quote))+'</mark>'+esc(cleanPDFBreaks(p.text.slice(h.end))):esc(cleanPDFBreaks(h.quote));
 $('#thread-source-content').innerHTML=`<div class="source-location"><strong>${esc(p.title)}</strong><small>${esc(h.location)} · ${exact?'Saved selection highlighted below':'Manually supplied quote — location not verified'}</small></div><label class="source-reflow"><input type="checkbox" id="source-reflow" checked> Join PDF line breaks for reading</label><article class="thread-source-paper" id="thread-source-paper">${html}</article>${!exact&&p.text?`<details class="source-context"><summary>Other source text saved for this paper</summary><div class="thread-source-paper">${esc(p.text)}</div></details>`:''}<div class="actions source-actions"><button data-source="${esc(h.id)}">Open in paper ↗</button>${exact?'<button id="focus-quote">Locate highlight</button>':''}</div><small class="help">Showing saved source text, not an automatically extracted PDF.</small>`;
 $('#source-reflow').onchange=e=>{const format=x=>esc(e.target.checked?cleanPDFBreaks(x):x);$('#thread-source-paper').innerHTML=exact?format(p.text.slice(0,h.start))+'<mark id="discussion-quote">'+format(h.quote)+'</mark>'+format(p.text.slice(h.end)):format(h.quote);};
 const focus=()=>{const box=$('#thread-source-paper'),m=$('#discussion-quote');if(m)box.scrollTop+=m.getBoundingClientRect().top-box.getBoundingClientRect().top-80;};if(exact){$('#focus-quote').onclick=focus;requestAnimationFrame(focus);}
}
function linkSources(t){modal('Link literature and passages',`<p>Select the exact passages this discussion concerns. Links are your associations, not AI-verified evidence.</p><form><h3>Literature</h3><div class="check-list">${alpha(data.papers).map(p=>`<label><input type="checkbox" name="paper" value="${esc(p.id)}" ${(t.paperIds||[]).includes(p.id)?'checked':''}><span>${esc(p.title)}</span></label>`).join('')||'<p>No literature added yet.</p>'}</div><h3>Passages</h3><div class="check-list">${data.passages.map(h=>`<label><input type="checkbox" name="passage" value="${esc(h.id)}" ${t.passageIds.includes(h.id)?'checked':''}><span>${esc(h.quote)}<small>${esc(getPaper(h.paperId)?.title)} · ${esc(h.location)}</small></span></label>`).join('')||'<p>No passages saved yet. Open a paper and save a passage first.</p>'}</div>${actions('Save source links')}</form>`,f=>{t.passageIds=f.getAll('passage');t.paperIds=f.getAll('paper');save();closeModal();renderThread();});}
function attachThread(id){modal('Link an existing discussion',`<form><div class="check-list">${data.threads.map(t=>`<label><input type="checkbox" name="thread" value="${esc(t.id)}" ${t.passageIds.includes(id)?'checked':''}><span>${esc(t.title)}<small>${esc(t.platform)}</small></span></label>`).join('')||'<p>No discussions imported yet.</p>'}</div>${actions('Save links')}</form>`,f=>{const ids=f.getAll('thread');for(const t of data.threads)t.passageIds=ids.includes(t.id)?[...new Set([...t.passageIds,id])]:t.passageIds.filter(x=>x!==id);save();closeModal();renderPassages();});}
document.addEventListener('click',e=>{const el=e.target.closest('[data-paper],[data-thread],[data-highlight],[data-jump],[data-import-for],[data-attach-thread],[data-source]');if(!el)return;const d=el.dataset;if(d.paper)openPaper(d.paper);else if(d.thread)openThread(d.thread);else if(d.importFor)importThread(d.importFor);else if(d.attachThread)attachThread(d.attachThread);else if(d.source){const h=data.passages.find(x=>x.id===d.source);openPaper(h.paperId,h.id);}else{activePassage=d.highlight||d.jump;renderPassages();$$('#source-text mark').forEach(m=>m.classList.toggle('active',m.dataset.highlight===activePassage));if(d.jump){showReaderSource(activePassage);}else document.getElementById('passage-'+activePassage)?.scrollIntoView({block:'nearest',behavior:'smooth'});}});
$('#zotero').onclick=()=>modal('Zotero / bibliography import',`<p>Live Zotero sync is not connected. Theesees can import bibliography records from a CSL-JSON file; PDFs, annotations, and collections are not imported.</p><form><label>Bibliography JSON<input type="file" name="bib" accept=".json,application/json" required></label><p class="help">Records remain local. Imported papers start without themes so you can choose how to organise them.</p>${actions('Import bibliography')}</form>`,async(f,form)=>{const file=form.elements.bib.files[0];if(file.size>5*1024*1024)throw Error('Use a bibliography file smaller than 5 MB.');let items;try{items=JSON.parse(await file.text());}catch{throw Error('This file is not valid JSON.');}if(!Array.isArray(items)||!items.every(x=>x&&typeof x.title==='string'))throw Error('Expected a CSL-JSON array of records with a title.');let n=0;for(const x of items){const signature=String(x.DOI||x.title).toLowerCase();if(data.papers.some(p=>String(p.doi||p.title).toLowerCase()===signature))continue;data.papers.push({id:uid(),title:x.title,author:(Array.isArray(x.author)?x.author:[]).map(a=>a.literal||[a.given,a.family].filter(Boolean).join(' ')).join(', '),year:String(x.issued?.['date-parts']?.[0]?.[0]||''),doi:typeof x.DOI==='string'?x.DOI:'',status:'To read',keywords:[],text:'',relevance:'',pdfName:''});n++;}save();closeModal();navigate('library');toast(`${n} bibliography records imported; duplicates skipped.`);});
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>{download('theesees-reading-records.json',{version:2,exportedAt:new Date().toISOString(),...data});toast('Exported records and source text. PDF files are not included.');};
function deleteItem(type,id){const item=type==='paper'?getPaper(id):getKeyword(id);if(!item)return;modal(type==='paper'?'Delete paper?':'Delete theme?',`<p><strong>${esc(item.title)}</strong></p><p>${type==='paper'?'The paper, its saved passages, and its source links will move to Trash. Original discussion transcripts stay unchanged. The deleted paper and PDF are kept in Trash for 30 days.':'The theme and its map connections will move to Trash. Its papers will stay in your library.'}</p><form>${actions('Move to Trash')}</form>`,()=>{const entry={id:uid(),type,item:structuredClone(item),at:new Date().toISOString()};if(type==='paper'){entry.passages=data.passages.filter(h=>h.paperId===id);const ids=new Set(entry.passages.map(h=>h.id));entry.links=data.threads.map(t=>({id:t.id,passageIds:t.passageIds.filter(x=>ids.has(x))})).filter(t=>t.passageIds.length);data.papers=data.papers.filter(p=>p.id!==id);data.passages=data.passages.filter(h=>h.paperId!==id);for(const t of data.threads)t.passageIds=t.passageIds.filter(x=>!ids.has(x));}else{entry.edges=data.edges.filter(e=>e.a===id||e.b===id);entry.paperIds=data.papers.filter(p=>p.keywords.includes(id)).map(p=>p.id);data.keywords=data.keywords.filter(k=>k.id!==id);data.edges=data.edges.filter(e=>e.a!==id&&e.b!==id);for(const p of data.papers)p.keywords=p.keywords.filter(k=>k!==id);selected=null;linkStart=null;linking=false;}data.trash.push(entry);save();closeModal();navigate('library');toast('Moved to Trash. You can restore it there.');});}
function showTrash(){modal('Trash',`<p>Restore a paper, theme, passage, or discussion. Deleted items expire after 30 days.</p><div class="trash-list">${data.trash.map(t=>`<article class="trash-row"><div><small>${t.type==='paper'?'PAPER':t.type==='passage'?'PASSAGE':t.type==='thread'?'DISCUSSION':'KEYWORD'}</small><h3>${esc(t.item.title||t.item.quote)}</h3></div><button data-restore="${esc(t.id)}">Restore</button></article>`).join('')||'<p class="help">No deleted items.</p>'}</div>`);}
function restoreItem(id){const entry=data.trash.find(t=>t.id===id);if(!entry)return;const item=entry.item;if(entry.type==='outline'){data.outline.parts.push(...entry.parts);}else if(entry.type==='claim'){restoreClaim(entry);}else if(entry.type==='thread'){data.threads.push(item);}else if(entry.type==='passage'){
 if(!getPaper(item.paperId)){toast('Restore the parent paper first, then restore this passage.');return;}
 data.passages.push(item);
 for(const tid of entry.threadIds||[]){const t=data.threads.find(t=>t.id===tid);if(t)t.passageIds=[...new Set([...t.passageIds,item.id])];}
 }else if(entry.type==='paper'){// Keep keyword IDs even while their keywords are in trash so either restore order works.
data.papers.push(item);data.passages.push(...entry.passages);for(const link of entry.links){const t=data.threads.find(t=>t.id===link.id);if(t)t.passageIds=[...new Set([...t.passageIds,...link.passageIds])];}}else{data.keywords.push(item);for(const pid of entry.paperIds){const p=getPaper(pid)||data.trash.find(t=>t.type==='paper'&&t.item.id===pid)?.item;if(p)p.keywords=[...new Set([...p.keywords,item.id])];}for(const edge of entry.edges){if(!data.edges.some(e=>e.id===edge.id))data.edges.push(edge);}}data.trash=data.trash.filter(t=>t.id!==id);save();render();showTrash();toast('Restored.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-delete-paper],[data-delete-keyword],[data-restore],[data-trash]');if(!b)return;if(b.dataset.deletePaper)deleteItem('paper',b.dataset.deletePaper);else if(b.dataset.deleteKeyword)deleteItem('keyword',b.dataset.deleteKeyword);else if(b.dataset.restore)restoreItem(b.dataset.restore);else showTrash();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-filter-keyword],[data-discussions-paper]');if(!b)return;discussionKeyword=b.dataset.filterKeyword||'all';discussionPaper=b.dataset.discussionsPaper||'all';discussionQuery='';archiveFilter='All';navigate('archive');});
render();if(storageProblem)toast('Could not read existing data. It has not been overwritten.');
function editPaperDetails(id){
 const p=getPaper(id);if(!p)return;
 modal('Edit literature details',`<form><label>Title<input name="title" required maxlength="500" value="${esc(p.title)}"></label><div class="two-col"><label>Author(s)<input name="author" value="${esc(p.author||'')}"></label><label>Year<input name="year" maxlength="20" value="${esc(p.year||'')}"></label></div><label>DOI (optional)<input name="doi" maxlength="200" value="${esc(p.doi||'')}" placeholder="10.1234/example"></label><label>APA reference <small id="apa-hint">*Asterisks* mark italics.</small><textarea name="apa" rows="3">${esc(p.apa||'')}</textarea></label><button type="button" id="gen-apa">${p.doi?'Generate from Crossref':'Generate from these details'}</button><input type="hidden" name="themes-shown" value="1"><label>Themes</label>${keywordChecks(p.keywords)}<p class="help">Your PDF, passages, discussions, and themes will stay linked.</p>${actions('Save changes')}</form>`,f=>{
  const title=f.get('title').trim();if(!title)throw Error('Enter a title.');
  const before={title:p.title,author:p.author,year:p.year,doi:p.doi,keywords:p.keywords,apa:p.apa};
  Object.assign(p,{title,author:f.get('author').trim(),year:f.get('year').trim(),...(f.has('doi')?{doi:f.get('doi').trim().replace(/^https?:\/\/(dx\.)?doi\.org\//i,'')}:{}),...(f.has('themes-shown')?{keywords:f.getAll('keyword')}:{}),...(f.has('apa')?{apa:f.get('apa').trim()}:{})});
  if(!save()){Object.assign(p,before);return;}
  closeModal();render();toast('Literature details updated.');
 });
 // Generate fills the box from the details as currently typed (online for a DOI; the user asked for it).
 const gen=$('#gen-apa');if(gen&&typeof generateAPA==='function')gen.onclick=async()=>{
  const form=$('#modal-body form'),draft={...p,title:form.elements.title.value.trim(),author:form.elements.author.value.trim(),year:form.elements.year.value.trim(),doi:form.elements.doi.value.trim()};
  gen.disabled=true;gen.textContent='Generating…';const r=await generateAPA(draft,{online:true});
  form.elements.apa.value=r.apa;$('#apa-hint').textContent=r.source==='Crossref'?'From Crossref.':'Built from these details — check it.';gen.disabled=false;gen.textContent='Generate again';
  if(draft.csl)p.csl=draft.csl;
 };
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-edit-paper]');if(b)editPaperDetails(b.dataset.editPaper);const t=e.target.closest('[data-edit-theme]');if(t)editKeyword(t.dataset.editTheme);});
